'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var expm1f = require( '@stdlib/math/base/special/expm1f' );
var expf = require( '@stdlib/math/base/special/expf' );
var log1pf = require( '@stdlib/math/base/special/log1pf' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var absf = require( '@stdlib/math/base/special/absf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var LN2 = require( '@stdlib/constants/float32/ln-two' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// MAIN //

/**
* Computes the natural logarithm of \\( 1-\exp(-|x|) \\) for a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = log1mexpf( 1.1 );
* // returns ~-0.40477
*
* @example
* var v = log1mexpf( 0.0 );
* // returns -Infinity
*
* @example
* var v = log1mexpf( NaN );
* // returns NaN
*/
function log1mexpf( x ) {
	var ax;

	x = f32( x );
	if ( isnanf( x ) ) {
		return NaN;
	}
	if ( x === 0.0 ) {
		return NINF;
	}
	ax = absf( x );
	if ( 0.0 < ax && ax <= LN2 ) {
		return lnf( f32( -expm1f( f32( -ax ) ) ) );
	}
	// Case: |x| > ln(2)
	return log1pf( f32( -expf( f32( -ax ) ) ) );
}


// EXPORTS //

module.exports = log1mexpf;
